+    throw new Error(
+      "DATAFN_PLACEMENT_CAS_REQUIRED: placement moves require compareAndSet",
+    );
+  }
+  const prefix = options.keyPrefix ?? PLACEMENT_KEY_PREFIX;
+  const key = (namespace: string) => `${prefix}${encodeURIComponent(namespace)}`;
