async function fetchPaged(endpoint, jq, label) {
  const items = [];
  for (let page = 1; ; page += 1) {
    const r = await tools.exec_command({
      cmd:`${gh}gh api '${endpoint}?per_page=10&page=${page}' --jq '${jq}'`,
      workdir, yield_time_ms:30000, max_output_tokens:50000
    });
    if (r.exit_code !== 0) { text(`${label} page ${page}\n${r.output}`); throw new Error(`${label} fetch failed`); }
    const batch = parseJsonOutput(r.output, `${label} page ${page}`);
    items.push(...batch);
    if (batch.length < 10) break;
  }
  return items;
}

